use axum::{extract::{Path, Query, State}, http::StatusCode};
use base64::{Engine, engine::general_purpose::URL_SAFE_NO_PAD};
use serde::{Deserialize, Serialize};

use crate::{
    domain::{
        models::entity_details::{
            EntityDetails, EntityIdentity, EntityReference, FunderIdentity, HistoryPage,
            InvalidDetailsRequest, MemberIdentity, RecordedDeclaration, RecordedFunding,
        },
        services::{
            entity_details::{EntityDetailsError, EntityDetailsService},
            entity_search::EntitySearchService,
        },
    },
    inbound::http::{error::ApiError, state::AppState, success::ApiSuccess},
};

pub(super) fn funder_reference(name: &str) -> String {
    URL_SAFE_NO_PAD.encode(name)
}

fn decode_funder_reference(reference: &str) -> Result<EntityReference, InvalidDetailsRequest> {
    let bytes = URL_SAFE_NO_PAD
        .decode(reference)
        .map_err(|_| InvalidDetailsRequest::FunderReference)?;
    let name = String::from_utf8(bytes).map_err(|_| InvalidDetailsRequest::FunderReference)?;
    EntityReference::funder(name)
}

#[derive(Deserialize)]
pub(super) struct DetailsQuery {
    #[serde(default = "default_limit")]
    limit: u16,
    #[serde(default)]
    offset: u32,
}

fn default_limit() -> u16 {
    50
}

#[derive(Serialize)]
pub(super) struct DetailsResponse {
    entity: IdentityResponse,
    declarations: Vec<DeclarationResponse>,
    pagination: PaginationResponse,
}

#[derive(Serialize)]
#[serde(tag = "kind")]
enum IdentityResponse {
    #[serde(rename = "MP")]
    Member(MemberResponse),
    Funder(FunderResponse),
}

#[derive(Serialize)]
struct MemberResponse {
    reference: String,
    details_url: String,
    member_id: i32,
    name: String,
    party_id: i32,
    party_name: String,
    latest_house: i16,
    latest_membership_from: String,
    is_current_commons: bool,
}

impl From<MemberIdentity> for MemberResponse {
    fn from(member: MemberIdentity) -> Self {
        Self {
            reference: member.member_id.to_string(),
            details_url: format!("/members/{}", member.member_id),
            member_id: member.member_id,
            name: member.name,
            party_id: member.party_id,
            party_name: member.party_name,
            latest_house: member.latest_house,
            latest_membership_from: member.latest_membership_from,
            is_current_commons: member.is_current_commons,
        }
    }
}

#[derive(Serialize)]
struct FunderResponse {
    reference: String,
    details_url: String,
    name: String,
    funder_kind: Option<String>,
    company_number: Option<String>,
}

impl From<FunderIdentity> for FunderResponse {
    fn from(funder: FunderIdentity) -> Self {
        let reference = funder_reference(&funder.name);
        Self {
            details_url: format!("/funders/{reference}"),
            reference,
            name: funder.name,
            funder_kind: funder.funder_kind,
            company_number: funder.company_number,
        }
    }
}

#[derive(Serialize)]
struct FundingResponse {
    funder: Option<FunderResponse>,
    amount: Option<String>,
    currency: Option<String>,
    payment_type: Option<String>,
}

impl From<RecordedFunding> for FundingResponse {
    fn from(funding: RecordedFunding) -> Self {
        Self {
            funder: funding.funder.map(FunderResponse::from),
            amount: funding.amount,
            currency: funding.currency,
            payment_type: funding.payment_type,
        }
    }
}

#[derive(Serialize)]
struct DeclarationResponse {
    source_declaration_id: i32,
    source_url: String,
    member: MemberResponse,
    category_id: i32,
    category_name: String,
    registration_date: Option<String>,
    fetched_at: String,
    funding_entries: Vec<FundingResponse>,
}

impl From<RecordedDeclaration> for DeclarationResponse {
    fn from(declaration: RecordedDeclaration) -> Self {
        Self {
            source_declaration_id: declaration.source_declaration_id,
            source_url: format!(
                "https://interests-api.parliament.uk/api/v2/Interests/{}",
                declaration.source_declaration_id
            ),
            member: declaration.member.into(),
            category_id: declaration.category_id,
            category_name: declaration.category_name,
            registration_date: declaration.registration_date.map(|date| date.to_string()),
            fetched_at: declaration.fetched_at.to_rfc3339(),
            funding_entries: declaration.funding_entries.into_iter().map(FundingResponse::from).collect(),
        }
    }
}

#[derive(Serialize)]
struct PaginationResponse {
    limit: u16,
    offset: u32,
    next_offset: Option<u32>,
}

impl DetailsResponse {
    fn new(details: EntityDetails, page: HistoryPage) -> Self {
        Self {
            entity: match details.entity {
                EntityIdentity::Member(member) => IdentityResponse::Member(member.into()),
                EntityIdentity::Funder(funder) => IdentityResponse::Funder(funder.into()),
            },
            declarations: details.declarations.into_iter().map(DeclarationResponse::from).collect(),
            pagination: PaginationResponse {
                limit: page.limit(),
                offset: page.offset(),
                next_offset: details.has_more.then(|| page.offset() + u32::from(page.limit())),
            },
        }
    }
}

impl From<InvalidDetailsRequest> for ApiError {
    fn from(error: InvalidDetailsRequest) -> Self {
        Self::UnprocessibleEntity(error.to_string())
    }
}

impl From<EntityDetailsError> for ApiError {
    fn from(error: EntityDetailsError) -> Self {
        match error {
            EntityDetailsError::NotFound => Self::NotFound,
            EntityDetailsError::Unavailable(cause) => {
                eprintln!("{cause}");
                Self::ServiceUnavailable
            }
        }
    }
}

pub(super) async fn member_details<E: EntitySearchService, D: EntityDetailsService>(
    State(state): State<AppState<E, D>>,
    Path(member_id): Path<String>,
    Query(query): Query<DetailsQuery>,
) -> Result<ApiSuccess<DetailsResponse>, ApiError> {
    let id = member_id.parse().map_err(|_| InvalidDetailsRequest::MemberId)?;
    details(&state, EntityReference::member(id)?, query).await
}

pub(super) async fn funder_details<E: EntitySearchService, D: EntityDetailsService>(
    State(state): State<AppState<E, D>>,
    Path(reference): Path<String>,
    Query(query): Query<DetailsQuery>,
) -> Result<ApiSuccess<DetailsResponse>, ApiError> {
    details(&state, decode_funder_reference(&reference)?, query).await
}

async fn details<E: EntitySearchService, D: EntityDetailsService>(
    state: &AppState<E, D>,
    reference: EntityReference,
    query: DetailsQuery,
) -> Result<ApiSuccess<DetailsResponse>, ApiError> {
    let page = HistoryPage::new(query.limit, query.offset)?;
    let details = state.entity_details_service.get_entity_details(&reference, page).await?;
    Ok(ApiSuccess::new(StatusCode::OK, DetailsResponse::new(details, page)))
}

#[cfg(test)]
mod tests {
    use super::{decode_funder_reference, funder_reference};

    #[test]
    fn names_round_trip_without_changing_case_spaces_or_url_characters() {
        for name in ["  Café / A&B + ?#%  ", "HSBC UK Bank plc", "HSBC UK Bank PLC"] {
            let reference = funder_reference(name);
            assert!(!reference.contains(['/', '+', '=']));
            assert_eq!(decode_funder_reference(&reference).unwrap().funder_name(), Some(name));
        }
        for invalid in ["***", "_w", "", "IA", "AA", "YQ=="] {
            assert!(decode_funder_reference(invalid).is_err(), "{invalid}");
        }
    }
}

