//! Search-to-detail API contracts against isolated PostgreSQL data and a fake port.

use std::sync::Arc;

use base64::{Engine, engine::general_purpose::URL_SAFE_NO_PAD};
use exposed::{
    domain::{
        models::{
            entity_details::{EntityDetails, EntityIdentity, EntityReference, FunderIdentity, HistoryPage},
            entity_search::{Entity, EntitySearchError, EntitySearchRequest},
        },
        repositories::entity_details_repository::{EntityDetailsRepo, EntityDetailsRepoError},
        services::{
            entity_details::{EntityDetailsError, EntityDetailsService, Service},
            entity_search::EntitySearchService,
        },
    },
    inbound::http::{routes::routes, server::app, state::AppState},
    outbound::ExposedDatabase,
};
use reqwest::StatusCode;
use serde_json::{Value, json};
use sqlx::PgPool;

struct TestServer {
    origin: String,
    task: tokio::task::JoinHandle<()>,
}

impl TestServer {
    async fn start(router: axum::Router) -> Self {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let origin = format!("http://{}", listener.local_addr().unwrap());
        let task = tokio::spawn(async move { axum::serve(listener, router).await.unwrap() });
        Self { origin, task }
    }

    async fn get(&self, path: &str) -> reqwest::Response {
        reqwest::get(format!("{}{path}", self.origin)).await.unwrap()
    }

    async fn json(&self, path: &str) -> Value {
        let response = self.get(path).await;
        assert_eq!(response.status(), StatusCode::OK, "{path}");
        serde_json::from_slice(&response.bytes().await.unwrap()).unwrap()
    }
}

impl Drop for TestServer {
    fn drop(&mut self) {
        self.task.abort();
    }
}

fn declaration_ids(response: &Value) -> Vec<i64> {
    response["declarations"].as_array().unwrap().iter()
        .map(|row| row["source_declaration_id"].as_i64().unwrap()).collect()
}

#[sqlx::test(migrations = "../db/migrations", fixtures("../../db/fixtures/entity_details.sql"))]
async fn member_selection_preserves_history_and_unknown_values(pool: PgPool) {
    let server = TestServer::start(app(ExposedDatabase::from(pool))).await;
    let search = server.json("/search?term=Casey&max_entries=10").await;
    let selected = &search["entities"][0];
    assert_eq!(selected["reference"], "1");
    assert_eq!(selected["kind"], "MP");
    let detail = server.json(selected["details_url"].as_str().unwrap()).await;
    assert_eq!(detail["entity"]["name"], selected["name"]);
    assert_eq!(detail["entity"]["party_name"], "Labour");
    assert_eq!(detail["entity"]["latest_membership_from"], "Example North");
    assert_eq!(declaration_ids(&detail), vec![103, 102, 101, 104]);
    assert_eq!(detail["declarations"][0]["funding_entries"], json!([]));
    assert_eq!(detail["declarations"][1]["funding_entries"], json!([{
        "funder": null, "amount": null, "currency": null, "payment_type": null
    }]));
    assert_eq!(detail["declarations"][0]["registration_date"], "2026-09-02");
    assert_eq!(detail["declarations"][0]["fetched_at"], "2026-09-20T12:34:56+00:00");
    assert_eq!(detail["declarations"][3]["registration_date"], Value::Null);
    assert_eq!(detail["declarations"][0]["source_url"],
        "https://interests-api.parliament.uk/api/v2/Interests/103");
    assert_eq!(detail["pagination"], json!({"limit": 50, "offset": 0, "next_offset": null}));

    let first = server.json("/members/1?limit=2").await;
    assert_eq!(declaration_ids(&first), vec![103, 102]);
    assert_eq!(first["pagination"]["next_offset"], 2);
    let second = server.json("/members/1?limit=2&offset=2").await;
    assert_eq!(declaration_ids(&second), vec![101, 104]);
    assert_eq!(second["pagination"]["next_offset"], Value::Null);
    let past_end = server.json("/members/1?offset=99").await;
    assert!(declaration_ids(&past_end).is_empty());
    assert_eq!(past_end["entity"]["member_id"], 1);
    assert!(declaration_ids(&server.json("/members/3").await).is_empty());

    let former = server.json("/members/2").await;
    assert_eq!(former["entity"]["latest_house"], 2);
    assert_eq!(former["entity"]["is_current_commons"], false);
    assert!(former["entity"].get("constituency").is_none());
}

#[sqlx::test(migrations = "../db/migrations", fixtures("../../db/fixtures/entity_details.sql"))]
async fn funder_selection_is_exact_and_keeps_all_declaration_context(pool: PgPool) {
    let server = TestServer::start(app(ExposedDatabase::from(pool.clone()))).await;
    let search = server.json("/search?term=Caf%C3%A9&max_entries=10").await;
    let results = search["entities"].as_array().unwrap();
    assert_eq!(results.len(), 2);
    let upper = results.iter().find(|entity| entity["name"] == "Café / A&B + ?#%").unwrap();
    let lower = results.iter().find(|entity| entity["name"] == "café / A&B + ?#%").unwrap();
    assert_ne!(upper["reference"], lower["reference"]);
    let url = upper["details_url"].as_str().unwrap();
    let detail = server.json(url).await;
    assert_eq!(detail["entity"]["reference"], upper["reference"]);
    assert_eq!(detail["entity"]["company_number"], "00123456");
    assert_eq!(declaration_ids(&detail), vec![105, 101, 104]);
    assert_eq!(detail["declarations"][0]["member"]["reference"], "2");
    assert_eq!(detail["declarations"][0]["funding_entries"][0]["currency"], "EUR");
    let funding = detail["declarations"][1]["funding_entries"].as_array().unwrap();
    assert_eq!(funding.len(), 3);
    assert_eq!(funding[0]["amount"], "12345678901234567890.123456789");
    assert_eq!(funding[0], funding[1]);
    assert_eq!(funding[2]["funder"]["reference"], lower["reference"]);
    assert_eq!(declaration_ids(&server.json(lower["details_url"].as_str().unwrap()).await), vec![106, 101]);
    let first = server.json(&format!("{url}?limit=1")).await;
    assert_eq!(declaration_ids(&first), vec![105]);
    assert_eq!(first["pagination"]["next_offset"], 1);

    // Import refresh replaces funding rows; the search reference still selects the name.
    let mut transaction = pool.begin().await.unwrap();
    sqlx::query("DELETE FROM exposed.funding_entries WHERE source_declaration_id = 105")
        .execute(&mut *transaction).await.unwrap();
    sqlx::query("INSERT INTO exposed.funding_entries (source_declaration_id, funder_id, amount, currency) SELECT 105, id, 9, 'GBP' FROM exposed.funders WHERE funder_name = $1")
        .bind("Café / A&B + ?#%").execute(&mut *transaction).await.unwrap();
    transaction.commit().await.unwrap();
    let refreshed = server.json(url).await;
    assert_eq!(refreshed["entity"], detail["entity"]);
    assert_eq!(refreshed["declarations"][0]["funding_entries"][0]["amount"], "9");

    let unused_url = format!("/funders/{}", URL_SAFE_NO_PAD.encode("Unused funder"));
    let unused = server.json(&unused_url).await;
    assert!(declaration_ids(&unused).is_empty());
    assert_eq!(unused["entity"]["funder_kind"], Value::Null);
}

#[sqlx::test(migrations = "../db/migrations", fixtures("../../db/fixtures/entity_details.sql"))]
async fn distinguishes_unknown_entities_from_invalid_requests(pool: PgPool) {
    let server = TestServer::start(app(ExposedDatabase::from(pool))).await;
    for path in ["/members/999", "/funders/bWlzc2luZw"] {
        assert_eq!(server.get(path).await.status(), StatusCode::NOT_FOUND, "{path}");
    }
    for path in ["/members/0", "/members/-1", "/members/nope", "/members/2147483648",
        "/funders/***", "/funders/_w", "/funders/IA", "/funders/AA", "/funders/YQ==",
        "/members/1?limit=0", "/members/1?limit=101", "/members/1?offset=2147483648"] {
        assert_eq!(server.get(path).await.status(), StatusCode::UNPROCESSABLE_ENTITY, "{path}");
    }
    for path in ["/members/1?limit=hello", "/members/1?offset=-1"] {
        assert_eq!(server.get(path).await.status(), StatusCode::BAD_REQUEST, "{path}");
    }
}

#[derive(Clone)]
enum FakeRepo {
    Empty,
    Missing,
    Unavailable,
}

impl EntityDetailsRepo for FakeRepo {
    async fn get_entity_details(&self, reference: &EntityReference, page: HistoryPage)
        -> Result<Option<EntityDetails>, EntityDetailsRepoError> {
        assert_eq!(reference.funder_name(), Some("Example"));
        assert_eq!(page.limit(), 50);
        assert_eq!(page.offset(), 0);
        match self {
            Self::Empty => Ok(Some(EntityDetails {
                entity: EntityIdentity::Funder(FunderIdentity {
                    name: "Example".into(), funder_kind: None, company_number: None,
                }),
                declarations: vec![], has_more: false,
            })),
            Self::Missing => Ok(None),
            Self::Unavailable => Err(EntityDetailsRepoError("private database diagnostic".into())),
        }
    }
}

#[derive(Clone)]
struct EmptySearch;

impl EntitySearchService for EmptySearch {
    async fn search_entities(&self, _: &EntitySearchRequest) -> Result<Vec<Entity>, EntitySearchError> {
        Ok(vec![])
    }
}

#[tokio::test]
async fn service_and_http_keep_read_failures_private_and_distinct() {
    let reference = EntityReference::funder("Example".into()).unwrap();
    let page = HistoryPage::new(50, 0).unwrap();
    let details = Service::new(FakeRepo::Empty).get_entity_details(&reference, page).await.unwrap();
    assert!(details.declarations.is_empty());
    assert!(matches!(Service::new(FakeRepo::Missing).get_entity_details(&reference, page).await,
        Err(EntityDetailsError::NotFound)));
    let failure = Service::new(FakeRepo::Unavailable).get_entity_details(&reference, page).await.unwrap_err();
    assert!(failure.to_string().contains("private database diagnostic"));

    let router = routes().with_state(AppState {
        entity_search_service: Arc::new(EmptySearch),
        entity_details_service: Arc::new(Service::new(FakeRepo::Unavailable)),
    });
    let server = TestServer::start(router).await;
    let response = server.get(&format!("/funders/{}", URL_SAFE_NO_PAD.encode("Example"))).await;
    assert_eq!(response.status(), StatusCode::SERVICE_UNAVAILABLE);
    assert_eq!(response.text().await.unwrap(), "entity details are temporarily unavailable");
}

